select jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'kind',c.relkind,
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated) order by conname) from pg_constraint where conrelid=c.oid),
'indexes',(select jsonb_agg(pg_get_indexdef(indexrelid) order by indexrelid::regclass::text) from pg_index where indrelid=c.oid),
'triggers',(select jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(t.oid),'enabled',tgenabled) order by tgname) from pg_trigger t where tgrelid=c.oid and not tgisinternal),
'policies',(select jsonb_agg(to_jsonb(p)-'oid'-'polrelid' order by polname) from pg_policy p where polrelid=c.oid)) order by n.nspname,c.relname) surface from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid in('public.notification_push_attempts'::regclass,'public.notification_deliveries'::regclass,'public.notification_push_devices'::regclass)
